<?php use App\Core\CSRF; ?>
<section class="container py-5" style="max-width:760px"><div class="card shadow-sm"><div class="card-body p-4"><h1 class="h3">Orçamento adicional</h1><p><?=htmlspecialchars($estimate['tenant_name'])?> · <?=htmlspecialchars(trim(($estimate['make']??'').' '.$estimate['model'].' '.($estimate['plate']??'')))?></p><div class="table-responsive"><table class="table"><tbody><?php foreach($items as $i):?><tr><td><?=htmlspecialchars($i['description'])?></td><td><?=number_format((float)$i['quantity'],2,',','.')?></td><td class="text-end">R$ <?=number_format((float)$i['total_amount'],2,',','.')?></td></tr><?php endforeach;?><tr class="fw-bold"><td colspan="2">Total</td><td class="text-end">R$ <?=number_format((float)$estimate['total_amount'],2,',','.')?></td></tr></tbody></table></div><p>Status: <strong><?=htmlspecialchars($estimate['status'])?></strong></p><?php if($estimate['status']==='sent'):?><form method="post" action="/auto/orcamento/<?=htmlspecialchars($token)?>" class="d-grid gap-2"><?=CSRF::field()?><textarea name="customer_note" class="form-control" placeholder="Observação opcional"></textarea><div class="d-flex gap-2"><button name="decision" value="approved" class="btn btn-success flex-fill">Aprovar</button><button name="decision" value="rejected" class="btn btn-outline-danger flex-fill">Recusar</button></div></form><?php elseif($estimate['status']==='approved'):?><div class="alert alert-success">Orçamento aprovado. A equipe já pode incluir os adicionais no atendimento.</div><?php elseif($estimate['status']==='rejected'):?><div class="alert alert-secondary">Orçamento recusado.</div><?php endif;?></div></div></section>
